{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Propafenone absolute oral bioavailability was 15.5% in 8 healthy subjects after oral vs i.v. dosing, below the 20% threshold, supporting low bioavailability."
    },
    {
      "card_ids": ["C08"],
      "claim": "DMT in ayahuasca had estimated absolute bioavailability of 10–15% based on i.v. comparison, below the 20% threshold, supporting low bioavailability."
    },
    {
      "card_ids": ["C20"],
      "claim": "Ketanserin absolute oral bioavailability was 50.4 ± 6.2% in ten healthy male subjects after a 40-mg oral dose, above the 20% threshold, contradicting a low prediction."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C20"],
  "decision_summary": "The highest-transfer and most numerous direct absolute-bioavailability records are below 20% (propafenone 15.5%, DMT 10–15%, plus sumatriptan, epanolol, agomelatine, eluxadoline), while only a few lower-transfer molecules show F ≥20% (ketanserin, tadalafil, fluvastatin). Therefore low is better supported.",
  "evidence_gaps": [
    "Assay-transfer scores do not identify the query; conflicting high-bioavailability evidence from tadalafil, ketanserin, and fluvastatin leaves residual uncertainty.",
    "Record C26 under Molecule 3 refers to BGG492 rather than sumatriptan; discounted as a provenance conflict.",
    "Fluvastatin evidence is formulation-dependent (extended-release 6% vs immediate-release 19–29%), adding uncertainty to the positive side."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C38", "C08"],
  "revision_action": "initial",
  "supportive_card_ids": ["C38", "C08"]
}

